<script setup lang="ts">
import {ElButton, ElInput, ElInputNumber, ElTable, ElTableColumn, ElPagination, vLoading} from 'element-plus'
import {computed,ref,watch} from 'vue'
import {onBeforeRouteLeave} from 'vue-router'
import {confirmAction} from '../../shared/confirm'
import {api,type Account} from '../../api'
import {base,reasonText,type ProductRatio,type PageResult} from './types'
import './dining.css'
const props=defineProps<{account:Account}>(),canManage=computed(()=>props.account.permissionCodes.includes('dining.manage'))
const items=ref<ProductRatio[]>([]),drafts=ref<Record<string,number|null>>({}),page=ref(1),total=ref(0),loading=ref(false),busy=ref(''),error=ref(''),search=ref(''),notice=ref('')
const dirty=computed(()=>items.value.some(i=>drafts.value[i.productId]!== (i.commissionBps===null?null:i.commissionBps/100)))
onBeforeRouteLeave(async()=>!dirty.value||await confirmAction('商品佣金比例尚未保存，确定离开吗？'))
let generation=0
async function reload(nextPage=page.value){if(dirty.value&&!await confirmAction('切换查询将丢弃未保存的商品佣金比例，确定继续吗？'))return;page.value=nextPage;await load()}
async function load(){const current=++generation;loading.value=true;error.value='';items.value=[];try{const result=await api<PageResult<ProductRatio>>(`${base}/product-ratios?${new URLSearchParams({page:String(page.value),pageSize:'20',search:search.value.trim()})}`);if(current===generation){items.value=result.items;total.value=result.total;drafts.value=Object.fromEntries(result.items.map(i=>[i.productId,i.commissionBps===null?null:i.commissionBps/100]))}}catch(e){if(current===generation)error.value=reasonText(e)}finally{if(current===generation)loading.value=false}}
async function save(item:ProductRatio){if(busy.value||!canManage.value)return;const percentage=drafts.value[item.productId];if(percentage===undefined||percentage===null||!Number.isFinite(percentage)||percentage<0||percentage>100){error.value='佣金比例必须在0%至100%之间。';return}const current=generation,preserved=Object.fromEntries(items.value.filter(i=>i.productId!==item.productId&&drafts.value[i.productId]!== (i.commissionBps===null?null:i.commissionBps/100)).map(i=>[i.productId,drafts.value[i.productId]??null]));busy.value=item.productId;error.value='';notice.value='';try{await api(`${base}/product-ratios`,{method:'PUT',body:JSON.stringify({productId:item.productId,commissionBps:Math.round(percentage*100),revision:item.revision})});if(current!==generation)return;await load();drafts.value={...drafts.value,...preserved};notice.value='商品佣金比例已保存，对所有餐饮店统一生效。'}catch(e){if(current===generation)error.value=`${reasonText(e)}；当前输入已保留，修订冲突时请记录输入后重新读取。`}finally{busy.value=''}}
watch(()=>[props.account.accountId,props.account.permissionCodes.join(',')],()=>{busy.value='';load()},{immediate:true})
</script>
<template><section class="page-content dining-page"><header class="page-heading"><div><h1>商品佣金比例</h1><p>同一商品对所有餐饮店统一生效。佣金＝（商品实付－履约前置仓进货单价×数量）×比例。</p></div></header><section class="panel"><form class="toolbar" @submit.prevent="reload(1)"><el-input v-model="search" aria-label="商品搜索" placeholder="搜索商品" style="width:280px"/><el-button native-type="submit" :loading="loading">查询</el-button></form><p v-if="error" role="alert" class="error">{{error}} <el-button :disabled="!!busy" @click="reload()">重新读取</el-button></p><p v-if="notice" role="status">{{notice}}</p><el-table v-loading="loading" :data="items" empty-text="暂无商品"><el-table-column prop="name" label="商品" min-width="220"/><el-table-column label="佣金比例" min-width="200"><template #default="{row}"><span v-if="row.commissionBps===null" class="muted">未配置 </span><el-input-number v-model="drafts[row.productId]" :aria-label="`${row.name}佣金比例`" :min="0" :max="100" :precision="2" :step="0.01" :disabled="!canManage||!!busy"/> %</template></el-table-column><el-table-column v-if="canManage" label="操作" width="100"><template #default="{row}"><el-button type="primary" :loading="busy===row.productId" :disabled="!!busy&&busy!==row.productId" @click="save(row as ProductRatio)">保存</el-button></template></el-table-column></el-table><el-pagination :current-page="page" :total="total" :page-size="20" layout="prev,pager,next,total" @current-change="reload($event)"/></section></section></template>
